function describe(mod) {
  const keys = Object.keys(mod);
  if (keys.includes("default")) console.log("default");
  else if (keys.length > 0) console.log("named");
  else console.log("none");
}
const modA = { default: { start() {} }, port: 3000 };
const modB = { port: 3000 };
describe(modA);
describe(modB);

